import assert from 'node:assert/strict';
import {test} from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return {promise, resolve, reject};
}

test('only the same ordered tenant and account pair shares a pending promise', async () => {
  const calls = [];
  const requests = [];
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    const request = deferred();
    requests.push(request);
    return request.promise;
  });

  const first = client('tenant:a', 'account');
  assert.strictEqual(client('tenant:a', 'account'), first);
  const otherTenant = client('tenant:b', 'account');
  const colonPairA = client('a:b', 'c');
  const colonPairB = client('a', 'b:c');
  const reversed = client('account', 'tenant:a');
  assert.notStrictEqual(otherTenant, first);
  assert.notStrictEqual(colonPairA, colonPairB);
  assert.notStrictEqual(reversed, first);

  await Promise.resolve();
  assert.deepEqual(calls, [
    ['tenant:a', 'account'],
    ['tenant:b', 'account'],
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['account', 'tenant:a'],
  ]);
  requests.forEach((request, index) => request.resolve(index));
  assert.deepEqual(await Promise.all([first, otherTenant, colonPairA, colonPairB, reversed]),
    [0, 1, 2, 3, 4]);
});

test('fulfillment clears the pending entry, including for a plain return value', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  const first = client('tenant', 'account');
  assert.strictEqual(client('tenant', 'account'), first);
  assert.equal(await first, 1);
  const second = client('tenant', 'account');
  assert.notStrictEqual(second, first);
  assert.equal(await second, 2);
  assert.equal(calls, 2);
});

test('rejection clears the pending entry and propagates the same error', async () => {
  const failure = new Error('load failed');
  const request = deferred();
  let calls = 0;
  const client = createBalanceClient(() => ++calls === 1 ? request.promise : 75);
  const first = client('tenant', 'account');
  assert.strictEqual(client('tenant', 'account'), first);
  await Promise.resolve();
  request.reject(failure);
  await assert.rejects(first, error => error === failure);
  assert.equal(await client('tenant', 'account'), 75);
  assert.equal(calls, 2);
});

test('a synchronous loader throw becomes a rejection and permits retry', async () => {
  const failure = new Error('synchronous failure');
  let calls = 0;
  const client = createBalanceClient(() => {
    if (++calls === 1) throw failure;
    return 0;
  });
  const first = client('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('tenant', 'account'), first);
  await assert.rejects(first, error => error === failure);
  assert.equal(await client('tenant', 'account'), 0);
});

test('singleFlight remains exported and accepts a key followed by loader arguments', async () => {
  const get = singleFlight((tenant, account) => [tenant, account]);
  assert.deepEqual(await get('key', 'tenant', 'account'), ['tenant', 'account']);
});

test('resolveBalance preserves monetary values and currency', async () => {
  for (const [balanceMinor, currency] of [
    [0, 'EUR'],
    [-125, 'JPY'],
    [Number.MAX_SAFE_INTEGER, 'KWD'],
  ]) {
    const result = await resolveBalance(
      createBalanceClient(() => ({balanceMinor, currency})), 'tenant', 'account');
    assert.deepEqual(result, {tenant: 'tenant', account: 'account', balanceMinor, currency});
  }
});

test('resolveBalance propagates client errors', async () => {
  const failure = new Error('balance unavailable');
  await assert.rejects(resolveBalance(() => { throw failure; }, 'tenant', 'account'),
    error => error === failure);
});

