import assert from 'node:assert/strict';
import {test} from 'node:test';
import {createBalanceClient} from '../src/client.mjs';
import {singleFlight} from '../src/pending.mjs';
import {resolveBalance} from '../src/resolve.mjs';

function deferred() {
  let resolve;
  const promise = new Promise((done) => { resolve = done; });
  return {promise, resolve};
}

test('concurrent requests for one ordered pair share a promise only while pending', async () => {
  const gate = deferred();
  const calls = [];
  const get = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return gate.promise;
  });

  const first = get('tenant', 'account');
  const second = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(first, second);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account']]);

  const balance = {balanceMinor: 42, currency: 'EUR'};
  gate.resolve(balance);
  assert.strictEqual(await first, balance);
  const later = get('tenant', 'account');
  assert.notStrictEqual(later, first);
  assert.strictEqual(await later, balance);
  assert.deepEqual(calls, [['tenant', 'account'], ['tenant', 'account']]);
});

test('tenant, account, and delimiter-containing strings identify independent requests', async () => {
  const pairs = [
    ['tenant-one', 'shared'],
    ['tenant-two', 'shared'],
    ['tenant:one', 'account'],
    ['tenant', 'one:account'],
  ];
  const calls = [];
  const gates = pairs.map(deferred);
  const get = createBalanceClient((tenant, account) => {
    const index = pairs.findIndex(([t, a]) => t === tenant && a === account);
    calls.push([tenant, account]);
    return gates[index].promise;
  });

  const results = pairs.map(([tenant, account]) => get(tenant, account));
  assert.equal(new Set(results).size, pairs.length);
  await Promise.resolve();
  assert.deepEqual(calls, pairs);

  gates.forEach((gate, index) => gate.resolve(index));
  assert.deepEqual(await Promise.all(results), [0, 1, 2, 3]);
});

test('singleFlight converts synchronous throws to rejections and retries after either failure', async () => {
  const error = new Error('lookup failed');
  let calls = 0;
  const get = singleFlight(() => {
    calls += 1;
    if (calls === 1) throw error;
    if (calls === 2) return Promise.reject(error);
    return {balanceMinor: 0, currency: 'JPY'};
  });

  const first = get('key');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('key'), first);
  await assert.rejects(first, (received) => received === error);
  assert.equal(calls, 1);

  const second = get('key');
  assert.notStrictEqual(second, first);
  await assert.rejects(second, (received) => received === error);
  assert.equal(calls, 2);

  const third = get('key');
  assert.deepEqual(await third, {balanceMinor: 0, currency: 'JPY'});
  assert.equal(calls, 3);
  assert.notStrictEqual(get('key'), third);
});

test('resolveBalance preserves monetary fields and propagates client errors', async () => {
  for (const [balanceMinor, currency] of [[0, 'JPY'], [-125, 'EUR'], [900, 'KWD']]) {
    const result = await resolveBalance(
      createBalanceClient((tenant, account) => {
        assert.equal(tenant, 'shop');
        assert.equal(account, 'cash');
        return {balanceMinor, currency};
      }),
      'shop',
      'cash',
    );
    assert.deepEqual(result, {tenant: 'shop', account: 'cash', balanceMinor, currency});
  }

  const error = new Error('service unavailable');
  await assert.rejects(
    resolveBalance(createBalanceClient(() => { throw error; }), 'shop', 'cash'),
    (received) => received === error,
  );
});

