export function singleFlight(load) {
  const pending = new Map();

  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Defer load until after the promise is stored, and turn synchronous throws
    // into rejections of that same promise.
    const promise = Promise.resolve().then(() => load(...args));
    pending.set(key, promise);

    // Handle both outcomes here. A discarded finally() promise would itself
    // reject when load fails and could create an unhandled rejection.
    const clear = () => { pending.delete(key); };
    promise.then(clear, clear);
    return promise;
  };
}

