import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import test from 'node:test';
import {createBalanceClient} from '../src/client.mjs';
import {singleFlight} from '../src/pending.mjs';
import {resolveBalance} from '../src/resolve.mjs';

test('same tenant and account share one pending Promise and original load arguments', async () => {
  const calls = [];
  let finish;
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return new Promise(resolve => { finish = resolve; });
  });

  const first = client('tenant:one', 'account:two');
  const second = client('tenant:one', 'account:two');
  assert.strictEqual(first, second);
  assert.ok(first instanceof Promise);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant:one', 'account:two']]);

  const balance = {balanceMinor: 42, currency: 'EUR'};
  finish(balance);
  assert.strictEqual(await first, balance);
  assert.strictEqual(await second, balance);
});

test('tenant, account, and colon boundaries keep pending requests independent', async () => {
  const calls = [];
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return {balanceMinor: calls.length, currency: 'USD'};
  });

  const requests = [
    client('tenant-a', 'shared'),
    client('tenant-b', 'shared'),
    client('a:b', 'c'),
    client('a', 'b:c'),
    client('left', 'right'),
    client('right', 'left'),
  ];
  assert.equal(new Set(requests).size, requests.length);
  assert.deepEqual((await Promise.all(requests)).map(value => value.balanceMinor), [1, 2, 3, 4, 5, 6]);
  assert.deepEqual(calls, [
    ['tenant-a', 'shared'], ['tenant-b', 'shared'],
    ['a:b', 'c'], ['a', 'b:c'],
    ['left', 'right'], ['right', 'left'],
  ]);
});

test('fulfillment clears pending entries so the next request reloads', async () => {
  let loads = 0;
  const client = createBalanceClient(() => ++loads);
  assert.equal(await client('tenant', 'account'), 1);
  assert.equal(await client('tenant', 'account'), 2);
  assert.equal(loads, 2);
});

test('rejection propagates and clears pending entries', async () => {
  const failure = new Error('lookup failed');
  let loads = 0;
  const client = createBalanceClient(() => {
    loads++;
    return loads === 1 ? Promise.reject(failure) : {balanceMinor: 7, currency: 'JPY'};
  });

  const first = client('tenant', 'account');
  assert.strictEqual(first, client('tenant', 'account'));
  await assert.rejects(first, error => error === failure);
  assert.deepEqual(await client('tenant', 'account'), {balanceMinor: 7, currency: 'JPY'});
  assert.equal(loads, 2);
});

test('a synchronous load throw becomes a rejected Promise and can be retried', async () => {
  const failure = new Error('synchronous failure');
  let loads = 0;
  const client = createBalanceClient(() => {
    if (++loads === 1) throw failure;
    return 9;
  });

  const first = client('tenant', 'account');
  assert.ok(first instanceof Promise);
  await assert.rejects(first, error => error === failure);
  assert.equal(await client('tenant', 'account'), 9);
});

test('rejection cleanup does not produce an unhandled rejection', () => {
  const moduleUrl = new URL('../src/pending.mjs', import.meta.url).href;
  const script = `
    import {singleFlight} from ${JSON.stringify(moduleUrl)};
    const get = singleFlight(() => Promise.reject(new Error('expected')));
    await get('key').catch(() => {});
    await new Promise(resolve => setImmediate(resolve));
  `;
  const result = spawnSync(process.execPath, [
    '--unhandled-rejections=strict', '--input-type=module', '--eval', script,
  ], {encoding: 'utf8'});
  assert.equal(result.status, 0, result.stderr);
});

test('singleFlight remains exported and forwards plain values', async () => {
  const get = singleFlight((left, right) => left + right);
  assert.equal(await get('sum', 2, 3), 5);
});

test('resolveBalance preserves zero, negative and large minor units with source currency', async () => {
  for (const [balanceMinor, currency] of [
    [0, 'EUR'], [-75, 'JPY'], [Number.MAX_SAFE_INTEGER, 'GBP'],
  ]) {
    const result = await resolveBalance(
      async (tenant, account) => {
        assert.equal(tenant, 'tenant');
        assert.equal(account, 'account');
        return {balanceMinor, currency};
      },
      'tenant', 'account',
    );
    assert.deepEqual(result, {tenant: 'tenant', account: 'account', balanceMinor, currency});
  }
});

test('resolveBalance propagates client errors', async () => {
  const failure = new Error('remote failure');
  await assert.rejects(
    resolveBalance(() => { throw failure; }, 'tenant', 'account'),
    error => error === failure,
  );
});

